.panel {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  width: 340px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

/* ── Cabecera ───────────────────────────────────────────────────────────── */

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  flex-shrink: 0;
  padding: 14px 16px;
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-divider-mist);
}

.eyebrow {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-brand);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  color: var(--bw-brass);
}

.title {
  margin: 0;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-input);
  font-weight: 700;
  line-height: 1.3;
  color: var(--bw-deep-steel);
}

.close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-top: -2px;
  border: none;
  border-radius: var(--bw-radius-hamburger);
  background: none;
  color: var(--bw-steel-mist);
  font-family: inherit;
  font-size: 18px;
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease;
}

.close:hover {
  background: var(--bw-hover-surface);
  color: var(--bw-deep-steel);
}

.close:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

/* ── Cuerpo: datos del FSR e historial ──────────────────────────────────── */

.body {
  display: flex;
  flex-direction: column;
  gap: 18px;
  flex: 1;
  padding: 16px;
  overflow-y: auto;
}

.sectionLabel {
  margin: 0 0 9px;
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
}

.field {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 7px;
}

.fieldLabel {
  flex-shrink: 0;
  min-width: 108px;
  padding-top: 1px;
  font-size: 11px;
  color: var(--bw-steel-mist);
}

.fieldValue {
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-ink-steel);
  word-break: break-all;
}

.valueMono {
  font-family: var(--bw-font-mono);
  font-size: 11px;
}

.extLink {
  color: var(--bw-calibration-blue);
  text-decoration: none;
}

.extLink:hover {
  text-decoration: underline;
}

.history {
  margin: 0;
  padding: 0;
  list-style: none;
}

.historyItem {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 8px;
  padding: 7px 0;
  border-bottom: 1px solid var(--bw-divider-mist);
}

.historyItem:last-child {
  border-bottom: none;
}

.historyDate {
  padding-top: 2px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-steel-mist);
}

.historyNote {
  flex: 1;
  min-width: 100%;
  font-size: 11px;
  color: var(--bw-steel-mist);
}

.historyLoading {
  margin: 0;
  font-size: 11px;
  color: var(--bw-steel-mist);
}

/* ── Badge de estado, también en el historial ───────────────────────────── */

.stateBadge {
  display: inline-block;
  flex-shrink: 0;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
}

.pending {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning-dark);
}

.approved {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.rejected {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
}

.cancelled {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

/* ── Pie: aviso, confirmaciones y acciones ──────────────────────────────── */

.footer {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-shrink: 0;
  padding: 14px 16px;
  border-top: 1px solid var(--bw-divider-mist);
}

.alert {
  padding: 8px 11px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  font-size: var(--bw-size-label);
  color: var(--bw-error-text);
}

.feedbackApprove {
  margin: 0;
  padding: 8px 11px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius);
  background: var(--bw-badge-success-bg);
  font-size: var(--bw-size-label);
  color: var(--bw-success-dark);
}

.feedbackReject {
  margin: 0;
  padding: 8px 11px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  font-size: var(--bw-size-label);
  color: var(--bw-error-text);
}

.actions {
  display: flex;
  gap: 8px;
}

.approve {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
  height: 36px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-signal-green);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.12s ease;
}

.approve:not(:disabled):hover {
  opacity: 0.87;
}

.reject {
  flex: 1;
  height: 36px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: none;
  color: var(--bw-sensitive-text);
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  transition: background 0.12s ease;
}

.reject:not(:disabled):hover {
  background: var(--bw-danger-hover-bg);
}

.return {
  height: 32px;
  padding: 0 14px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: none;
  color: var(--bw-steel-mist);
  font-family: inherit;
  font-size: var(--bw-size-label);
  cursor: pointer;
  transition: border-color 0.12s ease, color 0.12s ease;
}

.return:not(:disabled):hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.approve:disabled,
.reject:disabled,
.return:disabled,
.confirm:disabled,
.cancel:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ── Formulario de rechazo (spec §4) ────────────────────────────────────── */

.rejectForm {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.reason {
  min-height: 80px;
  padding: 8px 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-deep-steel);
  font-family: inherit;
  font-size: var(--bw-size-label);
  resize: vertical;
  outline: none;
  transition: border-color 0.12s ease;
}

.reason:focus {
  border-color: var(--bw-sensitive-text);
  box-shadow: var(--bw-focus-halo);
}

.reason::placeholder {
  color: var(--bw-input-placeholder);
}

.hint {
  margin: 0;
  font-size: 11px;
  color: var(--bw-steel-mist);
}

.formActions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.confirm {
  height: 34px;
  padding: 0 16px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-text);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: var(--bw-size-label);
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.12s ease;
}

.confirm:not(:disabled):hover {
  opacity: 0.87;
}

.cancel {
  height: 34px;
  padding: 0 12px;
  border: none;
  border-radius: var(--bw-radius);
  background: none;
  color: var(--bw-steel-mist);
  font-family: inherit;
  font-size: var(--bw-size-label);
  cursor: pointer;
  transition: color 0.12s ease;
}

.cancel:not(:disabled):hover {
  color: var(--bw-deep-steel);
}

import {
  isValidRejectionReason,
  requestDateLabel,
  websiteHref,
  type RequestEvent,
  type RequestRow,
  type RequestState,
} from '../../lib/admin-requests';
import styles from './RequestDetailPanel.module.css';

interface Props {
  row: RequestRow;
  history: RequestEvent[];
  historyLoading: boolean;
  rejecting: boolean;
  rejectReason: string;
  onRejectReasonChange: (v: string) => void;
  actionBusy: boolean;
  actionError: string | null;
  feedback: 'approved' | 'rejected' | null;
  onApprove: () => void;
  onStartReject: () => void;
  onConfirmReject: () => void;
  onCancelReject: () => void;
  onReturnToReview: () => void;
  onClose: () => void;
}

/**
 * El color del badge de estado. `styles` es un índice de strings —una clase
 * puede faltar en una build sin CSS—, así que el valor admite `undefined` y
 * quien lo compone lo descarta.
 */
const STATE_CLASS: Record<RequestState, string | undefined> = {
  PENDING_REVIEW: styles.pending,
  INVITED_APPROVED: styles.approved,
  REJECTED: styles.rejected,
  CANCELLED: styles.cancelled,
};

/**
 * El formato de fecha es SIEMPRE el de la capa de datos —aquí no se escribe
 * ninguna fecha a mano—, pero el instante se le pasa normalizado a su reloj UTC:
 * la cola del Operador se audita en UTC y así la misma solicitud no sale con una
 * hora distinta según la zona horaria de la máquina que la mira. En un entorno
 * en UTC el desplazamiento es cero.
 */
function utcClock(iso: string): string {
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return iso;
  return new Date(t + new Date(t).getTimezoneOffset() * 60_000).toISOString();
}

/**
 * Panel lateral de detalle de ADMIN-01.
 *
 * Totalmente controlado: no llama a ninguna función de red, no decide cuándo se
 * abre el formulario de rechazo —eso es de `AdminRequests`— y el textarea del
 * motivo no guarda su propio estado: su `value` es `rejectReason` y cada tecla
 * sale por `onRejectReasonChange`.
 */
export function RequestDetailPanel({
  row,
  history = [],
  historyLoading = false,
  rejecting,
  rejectReason = '',
  onRejectReasonChange,
  actionBusy,
  actionError,
  feedback,
  onApprove,
  onStartReject,
  onConfirmReject,
  onCancelReject,
  onReturnToReview,
  onClose,
}: Props) {
  /**
   * El pie: SOLO UNA de las ramas de decisión a la vez, en el orden de prioridad
   * de la spec. El `actionError` va aparte, encima: avisa y NO oculta la rama
   * que toque, para que el operador pueda reintentar sin perder los botones.
   */
  let decision: JSX.Element | null = null;

  if (feedback === 'approved') {
    // Texto literal de la tarea: NINGUNA mención a un email. El proveedor de
    // correo de EML-07/EML-08 no existe en el proyecto y esta pantalla no puede
    // afirmar un envío que no ocurre.
    decision = <p className={styles.feedbackApprove}>Aprobación registrada.</p>;
  } else if (feedback === 'rejected') {
    decision = <p className={styles.feedbackReject}>Solicitud rechazada.</p>;
  } else if (rejecting) {
    decision = (
      <div className={styles.rejectForm}>
        <textarea
          className={styles.reason}
          placeholder="Explica el motivo del rechazo — se enviará al solicitante"
          maxLength={500}
          value={rejectReason}
          onChange={(e) => onRejectReasonChange(e.target.value)}
        />
        <p className={styles.hint}>
          Este texto se incluirá en el email de rechazo (EML-08) · Mín 10 / máx 500 caracteres
        </p>
        <div className={styles.formActions}>
          <button
            type="button"
            className={styles.confirm}
            // La validación sale de la capa de datos: el `CHECK` de la base y
            // este botón no pueden discrepar (F-148).
            disabled={actionBusy || !isValidRejectionReason(rejectReason)}
            onClick={onConfirmReject}
          >
            Confirmar rechazo
          </button>
          <button
            type="button"
            className={styles.cancel}
            disabled={actionBusy}
            onClick={onCancelReject}
          >
            Cancelar
          </button>
        </div>
      </div>
    );
  } else if (row.state === 'PENDING_REVIEW') {
    decision = (
      <div className={styles.actions}>
        <button type="button" className={styles.approve} disabled={actionBusy} onClick={onApprove}>
          Aprobar
        </button>
        <button type="button" className={styles.reject} disabled={actionBusy} onClick={onStartReject}>
          Rechazar
        </button>
      </div>
    );
  } else if (row.state === 'REJECTED') {
    decision = (
      <button
        type="button"
        className={styles.return}
        disabled={actionBusy}
        onClick={onReturnToReview}
      >
        Volver a revisión
      </button>
    );
  }
  // INVITED_APPROVED y CANCELLED son estados de solo lectura: sin botones.

  return (
    <aside className={styles.panel} aria-label="Detalle de solicitud">
      <header className={styles.header}>
        <div>
          <p className={styles.eyebrow}>Detalle de solicitud</p>
          <h2 className={styles.title}>{row.orgName}</h2>
        </div>
        <button
          type="button"
          className={styles.close}
          aria-label="Cerrar panel de detalle"
          onClick={onClose}
        >
          ×
        </button>
      </header>

      <div className={styles.body}>
        <section>
          <h3 className={styles.sectionLabel}>Datos FSR</h3>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Empresa</span>
            <span className={styles.fieldValue}>{row.orgName}</span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>País</span>
            <span className={styles.fieldValue}>{`${row.countryLabel} · ${row.country}`}</span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Nombre solicitante</span>
            <span className={styles.fieldValue}>{row.applicantName}</span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Email</span>
            <span className={`${styles.fieldValue} ${styles.valueMono}`}>{row.email}</span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Teléfono</span>
            <span className={`${styles.fieldValue} ${styles.valueMono}`}>
              {row.phone === '' ? '—' : row.phone}
            </span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Sitio web</span>
            <span className={styles.fieldValue}>
              {row.website === '' ? (
                '—'
              ) : (
                <a
                  className={styles.extLink}
                  href={websiteHref(row.website)}
                  target="_blank"
                  rel="noreferrer"
                >
                  {row.website}
                </a>
              )}
            </span>
          </div>
          <div className={styles.field}>
            <span className={styles.fieldLabel}>Enviado</span>
            <span className={`${styles.fieldValue} ${styles.valueMono}`}>
              {requestDateLabel(utcClock(row.submittedAt))}
            </span>
          </div>
        </section>

        <section>
          <h3 className={styles.sectionLabel}>Historial de estado</h3>
          {historyLoading ? (
            <p className={styles.historyLoading}>Cargando historial…</p>
          ) : (
            <ul className={styles.history}>
              {history.map((event) => (
                <li key={event.id} className={styles.historyItem}>
                  <span className={`${styles.stateBadge} ${STATE_CLASS[event.state] ?? ''}`}>
                    {event.state}
                  </span>
                  <span className={styles.historyDate}>
                    {requestDateLabel(utcClock(event.at))}
                  </span>
                  {event.note !== '' && <span className={styles.historyNote}>{event.note}</span>}
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>

      <footer className={styles.footer}>
        {actionError !== null && (
          <div className={styles.alert} role="alert">
            {actionError}
          </div>
        )}
        {decision}
      </footer>
    </aside>
  );
}

