.tableOuter {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow-x: auto;
}

.table {
  width: 100%;
  min-width: max-content;
  border-collapse: collapse;
}

.th {
  padding: 9px 14px;
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.td {
  padding: 11px 14px;
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
  white-space: nowrap;
}

.table tbody tr:last-child .td {
  border-bottom: none;
}

.row {
  transition: background 0.1s ease;
}

.row:hover .td {
  background: var(--bw-row-hover-tint);
}

.rowSelected .td {
  background: var(--bw-tint-consulta);
}

/* ── Columna 1 · Organización ───────────────────────────────────────────── */

.orgButton {
  padding: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-calibration-blue);
  text-align: left;
  cursor: pointer;
}

.orgButton:hover {
  color: var(--bw-primary-dark);
  text-decoration: underline;
}

.orgButton:focus-visible {
  outline: none;
  border-radius: var(--bw-radius);
  box-shadow: var(--bw-focus-halo);
}

/* ── Columna 2 · País ───────────────────────────────────────────────────── */

.countryBadge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--bw-ink-steel);
}

/* ── Columna 5 · Sitio web ──────────────────────────────────────────────── */

.extLink {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  text-decoration: none;
}

.extLink:hover {
  color: var(--bw-calibration-blue);
  text-decoration: underline;
}

/* ── Columna 6 · Fecha de solicitud ─────────────────────────────────────── */

.timestamp {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
}

/* ── Columna 7 · Antigüedad en cola ─────────────────────────────────────── */

.age {
  font-family: var(--bw-font-mono);
  font-size: 11px;
}

.ageNormal {
  color: var(--bw-ink-steel);
}

.ageWarn {
  color: var(--bw-warning);
  font-weight: 500;
}

.ageAlert {
  color: var(--bw-danger);
  font-weight: 600;
}

/* ── Columna 8 · Estado ─────────────────────────────────────────────────── */

.stateBadge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
}

.pending {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning-dark);
}

.approved {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.rejected {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
}

.cancelled {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

/* ── Estado vacío (spec §6) ─────────────────────────────────────────────── */

.emptyCell {
  padding: 32px 16px;
  color: var(--bw-steel-mist);
  text-align: center;
}

